-- table: notes (207 rows, generated by scripts/s01_build_sample.py)
INSERT INTO "notes" ("note_id", "doc_id", "table_ids", "kind", "text", "page", "blocks_timeseries", "reason") VALUES
('biodic_6th_kanagawa_h16_n001', 'biodic_6th_kanagawa_h16', '[]', 'comparability', '前回の総合調査では、西丹沢のササ類や低木の密生したブナ林で記録されたが、局地的で個体数は少なかった。今回は5月から7月にかけて稜線を踏査したところ、前回と比較して分布域にほとんど違いはなかったが、前回は確認されたが今回は確認されなかったところがあったことから、減少している可能性がある。', 68, 1, '前回と今回で調査努力・確認地点が完全一致しておらず、未確認＝減少と断定できないため単純な経年比較は不可'),
('biodic_6th_kanagawa_h16_n002', 'biodic_6th_kanagawa_h16', '[]', 'comparability', '前回の総合調査では◯◯◯◯年以降の文献による記録をまとめ、主稜線周辺の◯◯◯◯m以上に少数が生息していることがわかった。今回は5月から7月の繁殖期に稜線を踏査したところ、2箇所だけで確認した。...以上のようなことから個体数は極めて少ないものと思われる。', 68, 1, '前回調査（文献記録の集約）と今回調査（現地踏査）で手法自体が異なり、確認数の単純比較はできない'),
('biodic_6th_kanagawa_h16_n003', 'biodic_6th_kanagawa_h16', '[]', 'comparability', '前回の総合調査で繁殖確認できた営巣地は、1か所であったが、現在その営巣地では6年連続繁殖していない。今回の調査では繁殖に対する阻害要因も明らかにしたい。', 70, 1, '前回調査時点で確認された営巣地1か所との比較のみであり、丹沢全体の個体群規模の経年比較指標としては不十分'),
('biodic_6th_kanagawa_h16_n004', 'biodic_6th_kanagawa_h16', '[]', 'footnote', '＊クマタカ調査は前回の総合調査から今回まで、神奈川野生生物研究会が継続して調査を実施してきた。', 70, 1, '同一団体による継続調査である旨のみが明記され、調査努力量や踏査範囲が前回と同一かは記載がないため、比較可能性は保証されない'),
('biodic_6th_kanagawa_h16_n005', 'biodic_6th_kanagawa_h16', '[]', 'comparability', 'ソウシチョウは前回の総合調査とほとんど分布が変わらなかったが、個体数は増えているように感じられた。', 72, 1, '「増えているように感じられた」は定量調査に基づく数値ではなく調査者の主観的印象であり、前回との個体数比較の根拠にはならない'),
('biodic_6th_kanagawa_h16_n006', 'biodic_6th_kanagawa_h16', '[]', 'comparability', '日本の河川の現存量は◯◯◯◯〜◯◯◯◯細胞（細胞計数の困難な藍藻などは糸状体数、以下省略）/mm²とされている。丹沢の今回の調査では◯◯〜◯◯◯◯細胞である（表1）。この数字から判明する事は、丹沢の藻類現存量は日本の河川としては値が小さいと言える。しかし、河川の付着藻の現存量は一般的に山地渓流の値は低く、平地河川では高いであるが、山地渓流の平均的な値の報告はない。', 39, 1, '比較対象となる「山地渓流の平均的な値」の全国的報告が存在しないと明記されており、日本の河川一般値との比較は参照基準が不足している'),
('biodic_6th_kanagawa_h16_n007', 'biodic_6th_kanagawa_h16', '["\u88689_\u6771\u4e39\u6ca2\u6d41\u6c34\u57df\u306e\u512a\u5360\u7a2e\u3068\u512a\u5148\u9806\u4f4d"]', 'definition_change', '注) ここでの優占種とは平均の出現率（100 / 出現taxa数）より大な種をいう。', 49, 1, '「優占種」の定義が本調査独自の計算式（100/出現taxa数）に基づくため、異なる定義を用いる他調査・他地点の優占種データとの単純比較は不可'),
('biodic_6th_kanagawa_h16_n008', 'biodic_6th_kanagawa_h16', '[]', 'survey_scope', 'ニホンジカ保護管理事業では、平成◯◯年度からシカの目撃情報の収集を行っている。総合調査では、ツキノワグマ、カモシカ、イノシシの目撃情報の収集を行った。平成◯◯年度1月現在、平成◯◯年度からのシカの目撃情報は◯◯◯◯件、平成◯◯年度から蓄積されていた情報、狩猟者登録証に記録された目撃情報を含めて、ツキノワグマ、カモシカ、イノシシの目撃情報は、それぞれ◯◯件、◯◯◯件、◯◯◯件であった。', 61, 1, '複数年度・複数情報源（一般目撃情報＋狩猟者登録証記録）を合算した累積件数であり、単年度間の単純増減比較には適さない'),
('biodic_6th_kanagawa_h16_n009', 'biodic_6th_kanagawa_h16', '[]', 'survey_scope', '本調査は一年という短い期間で行ったため、目録調査として不十分な点、生態学的調査として検証すべき点など課題も多い。これらについては、今後も継続調査することで解決していく必要がある。', 77, 1, '調査実施主体自身が単年データの網羅性・検証不足を明記しており、本報告の数値を経年トレンドの確定値として扱うべきではない'),
('biodic_6th_kanagawa_h16_n010', 'biodic_6th_kanagawa_h16', '["\u9644\u88682_\u672d\u639b\u30b3\u30a2\u30b5\u30a4\u30c8\u3067\u51fa\u73fe\u3057\u305f\u690d\u7269\u7a2e\u30ea\u30b9\u30c8"]', 'footnote', '（注）希少性区分は本文◯◯◯◯（表3）を参照。', 31, 0, '本文表3への単純な参照注記であり、比較可能性や時系列接続に影響する内容ではない'),
('n_higai_gaiyou2022_001', 'choju_higai_gaiyou_2022', '[]', 'definition_change', '※アライグマは令和３年度分までは「その他獣類」に含めて算出しています。', 1, 1, 'アライグマは令和4年度から独立した被害鳥獣区分として集計されるようになった。令和3年度以前は「その他獣類」に含まれていたため、「アライグマ」単独の経年比較はR4以降のみ可能で、R3以前と単純接続できない。同様に「その他獣類」区分もR4以降はアライグマ分が抜けるため、R3以前とR4以降で定義が変わっている。'),
('n_higai_gaiyou2022_002', 'choju_higai_gaiyou_2022', '[]', 'footnote', '※被害額は、千円止めで四捨五入していることにより、合計値は一致しない場合があります。', 1, 0, '四捨五入による内訳と合計の不一致に関する一般的な注記。C5(合計整合性)チェックで不一致が出ても、内訳を調整して合わせてはならない。'),
('n_higai_gaiyou2021_001', 'choju_higai_gaiyou_2021', '[]', 'footnote', '※被害額は、千円止めで四捨五入していることにより、合計値は一致しない場合があります。', 1, 0, '四捨五入注記。令和4年度版と同一文言。この年度の概況にはアライグマの区分変更に関する注記は見られない（R4版で初めて明記された）。'),
('n_higai_gaiyou2020_001', 'choju_higai_gaiyou_2020', '[]', 'footnote', '※被害額は、千円止めで四捨五入していることにより、合計値は一致しない場合があります。', 1, 0, '四捨五入注記。'),
('n_higai_gaiyou2019_001', 'choju_higai_gaiyou_2019', '[]', 'footnote', '※被害額は、千円止めで四捨五入していることにより、合計値は一致しない場合があります。', 1, 0, '四捨五入注記。'),
('n_higai_gaiyou2018_001', 'choju_higai_gaiyou_2018', '[]', 'footnote', '※被害額は、千円止めで四捨五入していることにより合計値は一致しない場合があります。', 1, 0, '四捨五入注記（読点の有無以外は他年度と同文）。'),
('n_higai_ssak2022_001', 'choju_higai_shichoson_sakumotsu_2022', '["p2_t1"]', 'footnote', '※四捨五入により合計が突合しない場合がある。', 2, 0, '四捨五入注記。'),
('n_higai_ssak2022_002', 'choju_higai_shichoson_sakumotsu_2022', '["p2_t1"]', 'definition_change', '※表中「0」は被害面積0.005ha未満、被害量0.0005t未満、被害額500円未満の場合。または積算資料がなく被害量、被害額が算出できなかった場合。', 2, 1, '表中の「0」表示が「実質ゼロ(僅少)」と「データが無く算出不能」という異なる状態を区別せずに同じ表記で示している。年度間で「0」の内訳（僅少なのか欠測なのか）が変化していても数値上は判別できないため、経年比較で「0」が続く区分は注意が必要。P6の「空欄と0と－を区別する」原則に照らしても、この0は真のゼロ値と保証されない。'),
('n_higai_ssak2021_001', 'choju_higai_shichoson_sakumotsu_2021', '["p2_t1"]', 'footnote', '※四捨五入により合計が突合しない場合がある。', 2, 0, '四捨五入注記。'),
('n_higai_ssak2021_002', 'choju_higai_shichoson_sakumotsu_2021', '["p2_t1"]', 'definition_change', '※表中「0」は被害面積0.005ha未満、被害量0.0005t未満、被害額500円未満の場合。または積算資料がなく被害量、被害額が算出できなかった場合。', 2, 1, 'choju_higai_shichoson_sakumotsu_2022と同一注記。「0」表示に僅少値と欠測が混在する。'),
('n_higai_ssak2020_001', 'choju_higai_shichoson_sakumotsu_2020', '["p2_t1"]', 'footnote', '※四捨五入により合計が突合しない場合がある。', 2, 0, '四捨五入注記。'),
('n_higai_ssak2020_002', 'choju_higai_shichoson_sakumotsu_2020', '["p2_t1"]', 'definition_change', '※表中「0」は被害面積0.005ha未満、被害量0.0005t未満、被害額500円未満の場合。または積算資料がなく被害量、被害額が算出できなかった場合。', 2, 1, '同上。「0」表示に僅少値と欠測が混在する。'),
('n_higai_ssak2019_001', 'choju_higai_shichoson_sakumotsu_2019', '["p2_t1"]', 'footnote', '※四捨五入により合計が突合しない場合がある。', 2, 0, '四捨五入注記。'),
('n_higai_ssak2019_002', 'choju_higai_shichoson_sakumotsu_2019', '["p2_t1"]', 'definition_change', '※表中「0」は被害面積0.005ha未満、被害量0.0005t未満、被害額500円未満の場合。または積算資料がなく被害量、被害額が算出できなかった場合。', 2, 1, '同上。'),
('n_higai_ssak2018_001', 'choju_higai_shichoson_sakumotsu_2018', '["p2_t1"]', 'footnote', '※四捨五入により合計が突合しない場合がある。', 2, 0, '四捨五入注記。'),
('n_higai_ssak2018_002', 'choju_higai_shichoson_sakumotsu_2018', '["p2_t1"]', 'definition_change', '※表中「0」は被害面積0.005ha未満、被害量0.0005t未満、被害額500円未満の場合。または積算資料がなく被害量、被害額が算出できなかった場合。', 2, 1, '同上。5年分(H30〜R4)すべての「市町村ー作物種類別」表に共通して付されている注記であることを確認した。'),
('n_higai_csak2022_001', 'choju_higai_choju_sakumotsu_2022', '["p2_t1"]', 'footnote', '※四捨五入により合計が突合しない場合がある。', 2, 0, '四捨五入注記。'),
('n_higai_csak2022_002', 'choju_higai_choju_sakumotsu_2022', '["p2_t1"]', 'definition_change', '※表中「0」は被害面積0.005ha未満、被害量0.0005t未満、被害額500円未満の場合。または積算資料がなく被害量、被害額が算出できなかった場合。', 2, 1, '「鳥獣別・作物種類別」表でも「0」表示が僅少値/欠測の両方を意味しうる。'),
('n_higai_csak2022_003', 'choju_higai_choju_sakumotsu_2022', '["p2_t1"]', 'definition_change', 'アライグマ 被害面積(ha) 0.01 2.33 0.12 0.21 0.58 3.24', 1, 1, '本表(鳥獣別・作物種類別)では令和4年度からアライグマが独立した行として集計されている。choju_higai_gaiyou_2022の注記の通り、令和3年度以前は「その他獣類」に含まれていたため、行単位の経年比較でアライグマ行がR3以前に存在しないのは欠測ではなく区分変更による。'),
('n_higai_csak2021_001', 'choju_higai_choju_sakumotsu_2021', '["p2_t1"]', 'footnote', '※四捨五入により合計が突合しない場合がある。', 2, 0, '四捨五入注記。'),
('n_higai_csak2021_002', 'choju_higai_choju_sakumotsu_2021', '["p2_t1"]', 'definition_change', '※表中「0」は被害面積0.005ha未満、被害量0.0005t未満、被害額500円未満の場合。または積算資料がなく被害量、被害額が算出できなかった場合。', 2, 1, '同上。'),
('n_higai_csak2020_001', 'choju_higai_choju_sakumotsu_2020', '["p2_t1"]', 'footnote', '※四捨五入により合計が突合しない場合がある。', 2, 0, '四捨五入注記。'),
('n_higai_csak2020_002', 'choju_higai_choju_sakumotsu_2020', '["p2_t1"]', 'definition_change', '※表中「0」は被害面積0.005ha未満、被害量0.0005t未満、被害額500円未満の場合。または積算資料がなく被害量、被害額が算出できなかった場合。', 2, 1, '同上。'),
('n_higai_csak2019_001', 'choju_higai_choju_sakumotsu_2019', '["p1_t1"]', 'footnote', '※四捨五入により合計が突合しない場合がある。', 1, 0, '四捨五入注記。'),
('n_higai_csak2019_002', 'choju_higai_choju_sakumotsu_2019', '["p1_t1"]', 'definition_change', '※表中「0」は被害面積0.005ha未満、被害量0.0005t未満、被害額500円未満の場合。または積算資料がなく被害量、被害額が算出できなかった場合。', 1, 1, '同上。'),
('n_higai_csak2018_001', 'choju_higai_choju_sakumotsu_2018', '["p1_t1"]', 'footnote', '※四捨五入により合計が突合しない場合がある。', 1, 0, '四捨五入注記。'),
('n_higai_csak2018_002', 'choju_higai_choju_sakumotsu_2018', '["p1_t1"]', 'definition_change', '※表中「0」は被害面積0.005ha未満、被害量0.0005t未満、被害額500円未満の場合。または積算資料がなく被害量、被害額が算出できなかった場合。', 1, 1, '5年分(H30〜R4)すべての「鳥獣別・作物種類別」表に共通する注記であることを確認した。'),
('n_higai_schoju2022_001', 'choju_higai_shichoson_choju_2022', '["p2_t1", "p2_t2"]', 'footnote', '※四捨五入により合計が突合しない場合がある。', 2, 0, '四捨五入注記。この「市町村ー鳥獣別」表はp1_maker.pyの一般的な表構造検出アルゴリズムでは正しく解析できず(市町村名・鳥獣種名が本来はデータ列であるにもかかわらずrow_keyとして誤結合され、C6違反(同一row_key/col_keyの組が多数重複)が358/864件検出された)、抽出結果全体の信頼性が低いことを別途報告する。この注記自体は本文に実在する。'),
('n_higai_schoju2021_001', 'choju_higai_shichoson_choju_2021', '["p2_t1", "p2_t2"]', 'footnote', '※四捨五入により合計が突合しない場合がある。', 2, 0, '四捨五入注記。この表は表構造抽出に問題があり(C6違反370/880件)、抽出結果全体の信頼性が低い。'),
('n_higai_schoju2020_001', 'choju_higai_shichoson_choju_2020', '["p2_t1", "p2_t2"]', 'footnote', '※四捨五入により合計が突合しない場合がある。', 2, 0, '四捨五入注記。この表は表構造抽出に問題があり(C6違反367/880件)、抽出結果全体の信頼性が低い。'),
('n_higai_schoju2019_001', 'choju_higai_shichoson_choju_2019', '["p1_t1"]', 'footnote', '※四捨五入により合計が突合しない場合がある。', 1, 0, '四捨五入注記。この表は表構造抽出に問題があり(C6違反85/288件)、抽出結果全体の信頼性が低い。'),
('n_higai_schoju2018_001', 'choju_higai_shichoson_choju_2018', '["p1_t1"]', 'footnote', '※四捨五入により合計が突合しない場合がある。', 1, 0, '四捨五入注記。この表は表構造抽出に問題があり(C6違反83/280件)、抽出結果全体の信頼性が低い。'),
('n_kyugo_j2017_001', 'choju_kyugo_jisseki_2017', '["p2_t1", "p2_t2"]', 'survey_scope', '＊平成29年度は鳥インフルエンザの影響で以下の期間、鳥類の受け入れを休止しました。
鳥類の受け入れ休止期間：横浜市立動物園：2017年12月～
川崎市立夢見ヶ崎動物公園：2018年1月～
保全センター：2018年1月11日～2月5日', 2, 1, '平成29年度は鳥インフルエンザ対策のため一部施設・期間で鳥類の受け入れを休止しており、年度内の鳥類救護件数が実際の傷病鳥獣発生数を反映していない。平成29年度の鳥類件数を他年度と単純比較すると過小評価になる。'),
('n_kyugo_j2017_002', 'choju_kyugo_jisseki_2017', '["p2_t1"]', 'definition_change', '＊（）はへい死体で持ち込まれたもので、内数', 1, 0, '括弧内の数値が「持ち込み時点で死亡していた個体数」を示す内数であることの定義。全体件数の一部であり、独立した別カウントではない点に注意。'),
('n_kyugo_j2017_003', 'choju_kyugo_jisseki_2017', '["p2_t1", "p2_t2"]', 'definition_change', '＊各年度の3月31日時点（へい死体除く）', 2, 0, '放野率・死亡率等の集計基準日と、へい死体(搬入時死亡)を除く対象範囲の定義。'),
('n_kyugo_j2017_004', 'choju_kyugo_jisseki_2017', '["p2_t1", "p2_t2"]', 'definition_change', '＊その他は治療中・終生飼養・長期飼養に移管したものなどを含む。', 2, 0, '転帰区分「その他」の定義。'),
('n_kyugo_j2016_001', 'choju_kyugo_jisseki_2016', '["p2_t1", "p2_t2"]', 'survey_scope', '＊平成 28 年度は鳥インフルエンザの影響で鳥類の受け入れを休止しているため、例年より鳥類の救護件数が変動しています。
鳥類の受け入れ休止期間：横浜市立及び川崎市立動物園：2016年12月～
保全センター：2017年2月8日～3月22日', 2, 1, '平成28年度も鳥インフルエンザ対策で鳥類受け入れを休止した期間があり、鳥類の救護件数が例年と異なる水準になっている。平成28・29年度は連続して鳥インフルエンザによる休止が発生しており、この2年度の鳥類データは前後の年度と同一条件で比較できない。'),
('n_kyugo_j2016_002', 'choju_kyugo_jisseki_2016', '["p2_t1"]', 'definition_change', '＊（）はへい死体で持ち込まれたもので、内数', 1, 0, 'n_kyugo_j2017_002と同一定義。'),
('n_kyugo_j2022_001', 'choju_kyugo_jisseki_2022', '["p2_t1"]', 'definition_change', '*その他は治療中・終生飼養・長期飼養に移管したものなどを含む。', 2, 0, '転帰区分「その他」の定義。年度間で表記の＊/*が変わっているが内容は同一。'),
('n_kyugo_j2021_001', 'choju_kyugo_jisseki_2021', '["p2_t1"]', 'definition_change', '*その他は治療中・終生飼養・長期飼養に移管したものなどを含む。', 2, 0, '転帰区分「その他」の定義。'),
('n_kyugo_j2020_001', 'choju_kyugo_jisseki_2020', '["p2_t1"]', 'definition_change', '*その他は治療中・終生飼養・長期飼養に移管したものなどを含む。', 2, 0, '転帰区分「その他」の定義。'),
('n_kyugo_j2019_001', 'choju_kyugo_jisseki_2019', '["p1_t1"]', 'definition_change', '＊（）はへい死体で持ち込まれたもので、内数', 1, 0, '内数の定義。'),
('n_kyugo_j2019_002', 'choju_kyugo_jisseki_2019', '["p2_t1"]', 'definition_change', '＊各年度の3月31日時点（へい死体除く）', 2, 0, '集計基準日の定義。'),
('n_kyugo_j2019_003', 'choju_kyugo_jisseki_2019', '[]', 'footnote', '＊ボランティア登録数は、各年度の3月31日現在', 4, 0, 'ボランティア登録数の集計基準日。'),
('n_kyugo_j2019_004', 'choju_kyugo_jisseki_2019', '[]', 'footnote', '＊各年度新たに依頼した分のみ掲載', 4, 1, '累計ではなく各年度新規分のみの掲載であることの明記。累計値と誤認して年度をまたいで加算すると二重計上を避けられる一方、経年での「累計」を見たい場合はこの表からは算出できない。'),
('n_kyugo_j2018_001', 'choju_kyugo_jisseki_2018', '["p1_t1"]', 'definition_change', '＊（）はへい死体で持ち込まれたもので、内数', 1, 0, '内数の定義。'),
('n_kyugo_j2018_002', 'choju_kyugo_jisseki_2018', '["p2_t1"]', 'definition_change', '＊各年度の3月31日時点（へい死体除く）', 2, 0, '集計基準日の定義。'),
('n_kyugo_j2014_001', 'choju_kyugo_jisseki_2014', '["p1_t1"]', 'definition_change', '＊（ ）は死体で持ち込まれたもので、内数', 1, 1, '他年度(2015〜2019)は「へい死体」という表現だが、2014年度版は「死体」という表現になっている。用語の揺れがあり、同一概念か厳密には要確認。定義文言が年度によって変化していること自体を記録する。'),
('n_ghg_suii2015_001', 'ghg_kencho_jikkou_suii_2015', '["p1_t1"]', 'definition_change', '３） 基準年度及び平成21年度の排出量を精査した結果、計画策定時の数値から補正を行いました。', 1, 1, '基準年度(平成20年度)と平成21年度の実績値が策定時から遡及修正されている。表中の基準年度比・増減率は改定後の数値で計算されているため、この文書より前に公表された数値と単純比較すると齟齬が出る。'),
('n_ghg_r4kencho_001', 'ghg_kencho_jissai_2022', '["p5_t1"]', 'definition_change', '※ 温室効果ガス排出量の算出には、各年度に定められた排出係数を用いて計算しています。また、端数処理により、合計等が整合しないことがあります。', 5, 1, '各年度の排出量は、その年度ごとに国が定めた電力排出係数を使って算出されている。つまり経年変化には実際の活動量の増減だけでなく、係数改定の影響が混入している。同じ表内で「基礎排出係数」ベースと「調整後排出係数」ベースの2系列の総排出量が併記されており、どちらの系列で経年比較するかで結果が変わる。'),
('n_ghg_r4kencho_002', 'ghg_kencho_jissai_2022', '["p5_t1"]', 'footnote', '算定に用いた「排出係数」は２種類あり、地球温暖化対策の推進に関する法律施行令に基づき公表された電気事業者毎の「基礎排出係数」及び「調整後排出係数」を使用しています。
（Ａ）「基礎排出係数」により算定した排出量：発電のために排出された二酸化炭素の量
（Ｂ）「調整後排出係数」により算定した排出量：「基礎排出係数」により算定した排出量から、環境価値相当量を差し引いた排出量', 5, 1, '総排出量に「基礎排出係数」版と「調整後排出係数」版の2系統があり、定義が異なる。どちらの系列かを明示せずに年度間比較すると誤った解釈になる。'),
('n_ghg_r4kencho_003', 'ghg_kencho_jissai_2022', '["p2_t1"]', 'footnote', '※電気の使用に伴う温室効果ガス排出量は、電気の使用量に、１kWh当たりの二酸化炭素排出量を乗じて計算していますが、この排出量の数値を電力の温室効果ガス排出係数といいます。この係数は電力会社ごとに異なり、毎年度、環境省が公表しています。', 2, 1, '電力由来排出量は「使用量×毎年度公表される排出係数」で算出され、係数自体が毎年変わる。エネルギー起源CO2の年度推移グラフ（2013〜2022年度）は、使用量の変化と係数の変化の両方を含んだ数値であることに注意が必要。'),
('n_ghg_kennai2021_001', 'ghg_kennai_suikei_2021', '[]', 'comparability', '推計に当たっては、推計方法の精度向上に努めており、毎年度必要な見直しを行っていることから、今回取りまとめた数値が、今後、再計算される場合があります。', 1, 1, '推計方法自体が毎年度見直され、過去に公表済みの数値も再計算(遡及改定)される可能性が明記されている。異なる年に公表された同一年度の数値を突き合わせると値が一致しないことがある。'),
('n_ghg_kennai2021_002', 'ghg_kennai_suikei_2021', '["p2_t1"]', 'comparability', '※２ 国全体と県の排出量の算定方法は同一ではない。', 2, 0, 'この注記は「県内」と「国全体」を横並びで比較する際の注意であり、神奈川県内数値の年度間(経年)比較そのものを妨げるものではない。ただし国比較を含む分析では明記が必要。'),
('n_ghg_kennai2021_003', 'ghg_kennai_suikei_2021', '[]', 'definition_change', '2013年度からの排出量の増加は、2016年４月の改正電気事業法の施行により電気事業者の区分が大幅に見直されたことに伴い、本推計で使用している統計資料において集計方法に変更がなされたことや世界的なＬＮＧ等のエネルギー需要ひっ迫を受け一時的に石炭・石油の使用量が増加したことによる。', 8, 1, 'エネルギー転換部門の排出量推計の元になっている統計資料の集計方法が2016年4月（改正電気事業法施行）を境に変更されている。2013年度以前と2016年度以降を同一の連続系列として単純比較すると、制度変更による段差を実態の増減と誤認する恐れがある。'),
('n_ghg_kennai2021_004', 'ghg_kennai_suikei_2021', '["p9_t1"]', 'footnote', '力の使用に伴う二酸化炭素排出量は、電力の消費量に二酸化炭素排出係数※を掛けて算出します', 9, 1, '表７「電力の二酸化炭素排出係数の経年変化」が示す通り、排出係数自体が年度ごとに変動する。電力由来排出量の経年推移には使用量の変化と係数の変化が両方含まれる。'),
('n_ghg_kennai2023_001', 'ghg_kennai_suikei_2023', '[]', 'comparability', '推計に当たっては、推計方法の精度向上に努めており、毎年度必要な見直しを行っていることから、今回取りまとめた数値が、今後、再計算される場合があります。', 1, 1, '2021年度版と同一文言。推計方法が年度ごとに見直され、公表済み数値が事後的に再計算されうることが明記されている。'),
('n_ghg_kennai2023_002', 'ghg_kennai_suikei_2023', '["p2_t1"]', 'comparability', '※２ 国全体と県の排出量の算定方法は同一ではない。', 2, 0, '県内数値どうしの経年比較は妨げないが、国全体との比較には算定方法の違いに留意が必要という注記。'),
('n_ghg_kennai2023_003', 'ghg_kennai_suikei_2023', '["p8_t1"]', 'definition_change', '※２ 本県の電力の二酸化炭素排出係数は、国が令和７年６月に改定した「地方公共団体実行計画（区域施策編）策定・実施マニュアル（算定手法編）」に基づき、「調整後排出係数」を使用しております。', 8, 1, '使用する排出係数の算定根拠マニュアル自体が令和7年6月に国により改定されている。表６「電力の二酸化炭素排出係数の経年変化」(2013〜2023年度)は、算定根拠が異なる期間を跨いだ数値である可能性がある。'),
('n_ghg_kennai2023_004', 'ghg_kennai_suikei_2023', '["p8_t1"]', 'definition_change', '（数値の補正）
○ 本推計において活用した2023年度の「都道府県別エネルギー消費統計」において、2022年度の家庭部門の電力消費量と、実際に消費された電力量を集計した「都道府県別電力需要実績」における家庭部門の電力需要量（低圧）との間に大きな乖離が生じていました。
〇 この問題を解消するため、国の総合エネルギー統計の補正方法を参考に、2021年度の家庭部門の電力消費量に、「都道府県別電力需要実績」における電力需要量（低圧）の2021年度から2022年度の変化率を乗じて補正を行いました。', 8, 1, '家庭部門の電力消費量について、2021・2022年度の基礎統計に乖離があったため独自の補正計算を行ったことが明記されている。家庭部門の経年推移を見る際、2021〜2022年度の数値は他の年度と算定過程が異なる点に注意が必要。'),
('n_ghg_kennai2023_005', 'ghg_kennai_suikei_2023', '["p8_t1"]', 'footnote', '（数値の更新）
○ 今回お知らせした神奈川県の2023年度速報値は、「都道府県別エネルギー消費統計」の2023年度「暫定値」を使用しており、「暫定値」ではなくなった際には、それに合わせて数値を更新します。', 8, 1, '最新年度の数値は「速報値・暫定値」であり、確定後に遡及改定される前提であることが明記されている。'),
('n_ghg_shinchoku_001', 'ghg_taisaku_keikaku_shinchoku_2024', '[]', 'definition_change', '※ 2020年度以降は、森林等による温室効果ガス吸収量を含む。', 4, 1, '県内の温室効果ガス排出量推移のグラフについて、2020年度を境に森林吸収量の扱いが変わっている（2020年度以降のみ吸収量を含む）。2019年度以前と2020年度以降を同一系列として単純比較すると、実際の排出削減と会計上の吸収量計上の効果が混同される。'),
('n_ghg_shinchoku_002', 'ghg_taisaku_keikaku_shinchoku_2024', '[]', 'definition_change', '○ 2013年度以降、推計で使用している統計資料において集計方法に変更がなされたことに伴い、2016年度に大きく減少した後は、緩やかな減少傾向にあり、これは、利用する電力のＣＯ排出原単位の改善により電力消費に伴う排出量が減少したこと、省エネルギー対策の進展等によりエネルギー消費原単位が改善したことが、主な要因と考えられます。', 9, 1, '業務部門のCO2排出量について、2016年度に統計の集計方法変更由来の段差があることが明記されている。ghg_kennai_suikei_2021のn_ghg_kennai2021_003と同じ2016年電気事業法改正に起因する変更。'),
('n_ghg_shinchoku_003', 'ghg_taisaku_keikaku_shinchoku_2024', '[]', 'survey_scope', '※2020年度のＣＯ２排出量は、新型コロナウイルス感染症の感染拡大に伴う経済活動の制限等の影響により、一時的に大きく数値が減少。', 7, 0, '2020年度単年の一時的な外的要因(コロナ禍の活動制限)による変動であることの説明であり、系列の定義や算定方法自体は変わっていない。ただし2020年度を含むトレンド解釈時には特筆すべき外れ値として扱う必要がある。同様の注記が複数部門(p7,p11,p13,p18)で個別に付されている。'),
('n_ghg_shinchoku_004', 'ghg_taisaku_keikaku_shinchoku_2024', '[]', 'footnote', '※ 温室効果ガスの排出量は端数処理（万 t-CO₂単位で四捨五入）をしているため、グラフ内の内訳と合計が一致しない場合があります。', 4, 0, '四捨五入による内訳と合計の不一致についての一般的な注記。P6ルールに基づき、合計が合わない場合でも内訳を調整して合わせてはならない。'),
('n_ghg_jikkoukeikaku_001', 'ghg_kencho_yokusei_jikkou_keikaku', '[]', 'definition_change', 'なお、二酸化炭素以外の温室効果ガスには、一酸化二窒素やメタンなどがあり、実行計画では５種類のガス1を対象としています。これらの５種類のガスを含めた温室効果ガスの総排出量については、参考として実績値のみ把握します。', 4, 1, '県庁の削減目標の指標は「エネルギー起源CO2」のみであり、他の4ガスを含む「総排出量」は目標管理の対象外で参考値扱いとされている。どちらの系列（起源CO2 or 総排出量）を時系列で追うかで意味が異なる。'),
('n_ghg_jikkoukeikaku_002', 'ghg_kencho_yokusei_jikkou_keikaku', '[]', 'survey_scope', '【計画の範囲】
知事部局、企業庁、議会局、教育委員会、人事委員会事務局等各事務局、警察本部、警察署が行う事務事業を対象', 4, 0, '「県庁が自ら排出した温室効果ガス」の集計範囲(組織)の定義。この範囲が過去の計画（jimujigyou_yokusei_keikaku等）と異なる可能性があるため、事務事業計画間の対象範囲の異同を比較する際の基礎情報として記録。'),
('n_ghg_jimujigyou_001', 'ghg_jimujigyou_yokusei_keikaku', '["p9_t1"]', 'definition_change', '前項で示した2008年度(平成20年度)の温室効果ガス排出量と異なるのは、2010年度(平成22年度)から地方独立行政法人へ移行する病院事業庁を除くとともに、業務委託施設及び指定管理施設を加えたことによるものです。また、警察については、庁舎以外の施設として新たに信号機の温室効果ガス排出量を加えました。', 9, 1, '同じ基準年度(2008年度)の排出量であっても、この計画の改定前後で集計対象組織(病院事業庁の除外、業務委託施設・指定管理施設・信号機の追加)が異なる版が存在することが明記されている。過去に公表された2008年度実績値と本計画の2008年度実績値を単純に同一視できない。'),
('n_ghg_jimujigyou_002', 'ghg_jimujigyou_yokusei_keikaku', '[]', 'definition_change', '温室効果ガス排出量の算定に係る排出係数
温室効果ガス排出量の算定に使用する排出係数の取扱いについて、「神奈川県地球温暖化防止実行計画」では、2006年度(平成18年度)に見直した際に、削減目標に対する対策の実施状況の評価等を行うため、計画期間中の排出係数を一定とすることとしました。（中略）本計画においては、基準年度(2008年度(平成20年度))に「地球温暖化対策の推進に関する法律施行令（平成21年３月31日政令第86号）」等により定められた排出係数を、計画期間中に継続して使用することとします。なお、毎年度の排出係数を使用して算出した温室効果ガス排出量を、参考として併せて公表します。', 12, 1, '県庁の目標管理上の排出量は基準年度(2008年度)時点の排出係数に固定して算定される一方、実際の毎年度係数を使った「参考」系列も別途存在する。r4ghg.pdf の「基礎排出係数」「調整後排出係数」の2系列表示と合わせ、神奈川県のCO2排出量には常に複数の算定方法の系列が並存することが確認できる。単一の「排出量」として時系列を扱う際は、どちらの算定方法の系列かを必ず明示する必要がある。'),
('n_ghg_jimujigyou_003', 'ghg_jimujigyou_yokusei_keikaku', '[]', 'definition_change', 'また、削減目標を設定する際の基準年度については、「神奈川県地球温暖化対策計画」と合わせて1990年度(平成２年度)とすることも検討しましたが、「神奈川県地球温暖化防止実行計画」に基づく取組により、2008年度(平成20年度)の温室効果ガス排出量(181,953.7t-CO2)は、1990年度(平成２年度)の排出量(推計値：186,471t-CO2)を下回っていること、また、本計画の対象とする県の組織や事務・事業が1990年度(平成２年度)当時と大きく変わっていることから、直近の2008年度(平成20年度)を基準年度として設定します。', 11, 1, '削減目標の基準年度が計画改定のたびに変遷している(1990年度→2008年度、その後さらに現行計画では2013年度)。基準年度比の増減率だけを追うと、実際にはどの基準年度に対する比較かが版によって異なることに注意が必要。'),
('h20-n1', 'kanagawa_river_monitoring_h20_sagami_results', '[]', 'footnote', 'サンショウウオ類は、貴重種のため詳細な分布情報の公開はしない。', 14, 1, '当該分類群は分布データが非公開のため、年度間の空間比較ができない。'),
('h20-n2', 'kanagawa_river_monitoring_h20_sagami_results', '[]', 'comparability', '6地点（小倉橋、昭和橋、第2鮎津橋、酒井橋、馬船橋、平泉橋）について、BOD、SS、窒素及び全リンの結果を「公共用水域水質調査結果」2005年度及び2006年度と比較した(図-５)。', 7, 0, '比較対象は40地点中6地点のみに限定されており、全地点の経年比較には使えない。'),
('h20-n3', 'kanagawa_river_monitoring_h20_sagami_results', '[]', 'comparability', '5月はBOD、SS、全リンが他の月と比較して高かった。これは直前の降雨の影響と考えられる。', 7, 1, '降雨等の気象条件により月別値が変動することが明記されており、単純な月次・年次比較は気象条件の違いを考慮しないと誤解を招く。'),
('h20-n4', 'kanagawa_river_monitoring_h20_sagami_results', '[]', 'survey_scope', '本川、支川、渓流を含む相模川水系40地点（図-１、表-１）。ただしサンショウウオ類は25地点', 3, 0, '調査地点数が分類群によって異なることを明示。サンショウウオ類とその他分類群を同一地点数で比較しないよう注意が必要。'),
('h20-n5', 'kanagawa_river_monitoring_h20_sagami_results', '[]', 'definition_change', '底生動物の科（Family）に対して水質汚濁などの人為的な影響の弱いものから強いものへ順に10から1までのスコアを与え、出現したすべての科のスコアの合計値（総スコア値）を科数で割ったもの。', 14, 0, '平均スコア法の定義文言が本書では『人為的な影響』表現だが、後年（H21以降）は『耐忍性』表現に変わっており、算出式自体は同一ながら説明文言の変化がある。'),
('h21-n1', 'kanagawa_river_monitoring_h21_sakawa_results', '[]', 'comparability', '9地点（十文字橋、報徳橋、小田原大橋上、新鮎沢橋、中川温泉下、玄倉水位観測所、浅瀬、文久橋、狩川橋）について、ＢＯＤ、ＳＳ、全窒素及び全リンの結果を「公共用水域水質調査結果」2005年度〜2008年度と比較した(図-５)。', 7, 0, '比較対象は40地点中9地点のみに限定されており、全地点の経年比較には使えない。'),
('h21-n2', 'kanagawa_river_monitoring_h21_sakawa_results', '[]', 'survey_scope', '相模川流域・酒匂川流域や都市部の支川を含む任意の地点および時期に調査を行った。', 3, 1, '県民参加型調査は地点・時期が年度ごとに任意で固定されておらず、年度間の定点比較には使えない。'),
('h21-n3', 'kanagawa_river_monitoring_h21_sakawa_results', '[]', 'comparability', '底生動物による水質を主眼とした環境評価（平均スコア法※）の階級分布を図-６(2)に示す。種類数は中・上流の地点で多い傾向がみられたがあまり差は明確ではなかった。', 14, 0, '著者自身が地点間の差が明確でないと留保しており、地点間比較の解釈に注意が必要。'),
('h21-n4', 'kanagawa_river_monitoring_h21_sakawa_results', '[]', 'definition_change', '底生動物の科（Family）に対して水質汚濁への耐忍性の弱いものから強いものへ順に10から１までのスコアを与え、出現したすべての科のスコアの合計値（BMWPスコア値）を科数で割ったもの。注）BMWP：イギリスにおいて生物学的水質評価法を標準化するために作られたワーキンググループ（Biological Monitoring Working Party）。(1976)', 14, 0, 'H20版の説明文言『人為的な影響の弱いものから強いものへ』から『水質汚濁への耐忍性の弱いものから強いものへ』に表現が変化し、BMWPという用語・出典注が新たに追加された。算出式(ASPT=ΣSi／ｎ)自体は同一。'),
('h21-n5', 'kanagawa_river_monitoring_h21_sakawa_results', '[]', 'footnote', 'サンショウウオ類は主に源流近くで確認された。', 15, 0, 'H20報告書にあった『貴重種のため詳細な分布情報の公開はしない』という非公開の断り書きが本書には見当たらず、記載の有無が年度で異なる。'),
('h25-n1', 'kanagawa_river_monitoring_h25_sagami_results', '[]', 'comparability', '40地点について、BOD,SS、全窒素及び全燐の結果を平成20年度調査結果と比較した(図-7)。', 7, 0, '比較は平成20年度と平成25年度の2時点のみで実施地点数・方法は同一と読めるが、間の年度データは含まれない。'),
('h25-n2', 'kanagawa_river_monitoring_h25_sagami_results', '[]', 'comparability', '2月はSS、全窒素及び全燐がやや高かったが、これは、降雪の影響の可能性も考えられる。', 7, 1, '気象（降雪）の影響で特定月の値が変動したことを明記しており、単純な月次比較は気象条件差を考慮する必要がある。'),
('h25-n3', 'kanagawa_river_monitoring_h25_sagami_results', '[]', 'definition_change', '全窒素は年平均1.6mg/Lで、そのほとんどが硝酸性窒素１）であった。また、全燐は年平均0.036mg/Lで、その多くは燐酸態燐２）（0.025mg/L）であった。', 7, 1, 'H20/H21では『全リン』『リン酸態リン』とカタカナ表記だったが、本書（H25）以降は『全燐』『燐酸態燐』と漢字表記に変わっている。同一指標だが表記が変わっており、文字列一致による時系列突合を行う際は注意が必要。'),
('h25-n4', 'kanagawa_river_monitoring_h25_sagami_results', '[]', 'footnote', '全調査地点の40地点全て で確認された種は、ウルマーシマトビケラ、ニセテンマクエリユスリカ属、エリユスリカ亜科、ハモンユスリカ属の4種であった。ただし、エリユスリカ亜科については、複数の不明属を含む可能性が高い。', 14, 1, '同定精度に関する留保（不明属を含む可能性）が明記されており、種数の年度間比較の精度に影響しうる。'),
('h25-n5', 'kanagawa_river_monitoring_h25_sagami_results', '[]', 'comparability', '底生動物による環境評価（平均スコア法※）の年度比較を図-９に示す。平成20年度調査と同様に平均スコアの値は上流で高く、下流になるに従い低くなる傾向がみられた。', 14, 0, '平成20年度との定性的傾向比較であり、数値の単純比較の妥当性については言及がない。'),
('h25-n6', 'kanagawa_river_monitoring_h25_sagami_results', '[]', 'footnote', 'カエル類の代表種として、神奈川県レッドデータ生物調査報告書2006の希少種であるナガレタゴガエルの分布の年度比較を図-11に示す。サンショウウオ類は主に宮ヶ瀬湖の上流で確認された。', 14, 0, 'H20報告書にあった『サンショウウオ類の詳細分布は非公開』という断り書きが本書には明記されておらず、代表種もカジカガエルからナガレタゴガエルに変更されている。'),
('h26-n1', 'kanagawa_river_monitoring_h26_sakawa_results', '[]', 'footnote', '（エ）平成20年度調査結果との比較
 40地点の年平均値について、BOD,SS、全窒素及び全燐の結果を平成21年度調査結果と比較した(図-7)。', 7, 1, '小見出しは『平成20年度調査結果との比較』だが本文は『平成21年度調査結果と比較』としており、見出しと本文の年度表記が一致していない（酒匂川調査は平成21年度が前回のはずで、平成20年度は相模川報告書の年度）。誤記の可能性が高く、機械的な年度突合を誤らせるおそれがある。'),
('h26-n2', 'kanagawa_river_monitoring_h26_sakawa_results', '[]', 'comparability', 'カジカは、相模川では開空率の増加に伴い減少、酒匂川では攪乱の増加に伴い増加したと考えられた。', 14, 1, '同一種でも河川間で増減の方向・要因が逆であると明記されており、河川を跨いだ単純比較はできない。'),
('h26-n3', 'kanagawa_river_monitoring_h26_sakawa_results', '[]', 'comparability', 'ワンド・たまりで繁殖する両生類の分布状況は出水等により変化するものの、水系全体での生息状況は安定していると考えられた。', 14, 1, '出水（増水）等の一時的な攪乱要因により分布が変動しうることが明記されている。'),
('h26-n4', 'kanagawa_river_monitoring_h26_sakawa_results', '[]', 'comparability', 'ナルコスゲは相模川水系と酒匂川水系で異なる変化傾向で、相模川では増加しているが酒匂川では減少していた。また、確認地点数が減少した種は酒匂川に多いという結果になっており、鳥類と同様に酒匂川の出水の影響を受けて変化している可能性があると考えられた。', 14, 1, '確認地点数の減少が『出水の影響』による可能性があると明記されており、年度間の減少を生物学的トレンドと解釈すると誤る可能性がある。'),
('h26-n5', 'kanagawa_river_monitoring_h26_sakawa_results', '[]', 'comparability', '相模川では特に下流域の支川でDAIpoが大きく減少しており、酒匂川においては、本川も含めて全体的にDAIpoが下がる傾向にあった。付着藻類の出現に影響する水質や開空率の変化を整理したが、大きな変化はみられず、他の要因が影響していると考えられた。', 15, 1, 'DAIpoの低下要因が特定できず『他の要因』と留保されている。また本書は酒匂川の報告書だが本文に『相模川では』という記述が混在しており、記載の出典・対象範囲に注意が必要（テンプレート流用の可能性）。'),
('h30-n1', 'kanagawa_river_monitoring_h30sagamigawa', '[]', 'survey_scope', '本川、支川、渓流を含む相模川水系39地点（図-１、表-１）。ただしサンショウウオ類は源流域25地点
(前回までの調査地点は40地点だったが、崩落が発生したため1地点減)', 3, 1, '調査地点数が前回（平成25年度）の40地点から39地点へ、崩落を理由に変更されたことが明記されている。地点集合が変わったため全地点平均値等の単純な年度間比較はできない。'),
('h30-n2', 'kanagawa_river_monitoring_h30sagamigawa', '[]', 'footnote', '崩落により調査不可', 5, 1, '表-1の地点状況表で該当地点（No.20 宮ヶ瀬金沢・宮ヶ瀬付近）が調査不能であったことを示す注記。地点脱落の直接証拠。'),
('h30-n3', 'kanagawa_river_monitoring_h30sagamigawa', '[]', 'comparability', '39地点について、BOD、SS、全窒素及び全リンの結果を平成20年度調査結果と比較した(図-７)。', 7, 1, '本文は『平成20年度調査結果との比較』とのみ記すが、図-7のキャプションは『平成20、25年度調査結果との比較』であり2時点比較であることが図側にしか明記されていない。加えて地点数が39（前回40）であるため比較対象地点集合も完全一致しない。'),
('h30-n4', 'kanagawa_river_monitoring_h30sagamigawa', '[]', 'definition_change', 'リン酸態リン：燐酸態燐は、燐酸イオンとして存在する燐のことで、栄養塩として藻類に吸収利用されるため富栄養化現象の直接的な原因物質になる。', 7, 0, '見出し語は『リン酸態リン』（カタカナ、H20/H21/H30本文の主表記）だが、脚注の説明文自体はH25/H26で使われていた『燐酸態燐』（漢字）の文章がそのまま残っており、同一書類内で表記が不統一。'),
('h30-n5', 'kanagawa_river_monitoring_h30sagamigawa', '[]', 'footnote', '地点名の表記変更: No.5『自然公園センター前』→『旧自然公園センター前』、No.21『布川・唐沢川』→『布川・札掛橋下流』、No.22『布川・金沢キャンプ場』→『布川・旧金沢キャンプ場』、No.30『荻野川・新道橋』の写真キャプションは『萩野川・新道橋』と異なる漢字表記。', 5, 1, '複数の調査地点で名称・漢字表記が過去年度から変更されており、地点名の文字列一致による過去データとの突合が失敗しうる。'),
('h30-n6', 'kanagawa_river_monitoring_h30sagamigawa', '[]', 'footnote', 'No.g40、No.g39のように地点番号に「g」が付与された表記が本文中で使われている（例：No.g40（平泉橋）、No.g32(酒井橋)）。', 7, 0, 'H20/H25では『No.40』のように接頭辞なしで表記していたが、本書では『No.g40』のように接頭辞『g』付きの新しい地点番号表記が使われている。文字列一致でのID突合を行う場合は接頭辞の有無に注意が必要。'),
('r1-n1', 'kanagawa_river_monitoring_r1_sakawa_results', '[]', 'survey_scope', '本川、支川、渓流を含む酒匂川水系39地点（図-１、表-１）。 ただしサンショウウオ類は25地点', 3, 1, '平成26年度report(40地点)から39地点に減少している。理由は表-1の『崩落のため未調査』注記に対応すると考えられ、地点集合の変更のため単純な全地点平均の経年比較はできない。'),
('r1-n2', 'kanagawa_river_monitoring_r1_sakawa_results', '[]', 'footnote', '崩落のため未調査', 5, 1, '表-1の地点状況表で該当地点が調査不能であったことを示す注記。地点脱落の直接証拠（h30と同種の崩落起因の欠測）。'),
('r1-n3', 'kanagawa_river_monitoring_r1_sakawa_results', '[]', 'footnote', '（エ）過度調査結果との比較
 39地点の年平均値について、BOD,SS、全窒素及び全燐の結果を過年度(平成21年度および平成26年度)調査結果と比較した(図-7)。', 7, 1, '見出し・本文とも『過年度』とすべきところが『過度』という誤記になっている（図-7キャプションも同様に『過度調査結果との比較』）。誤記のため、テキスト検索や年度キーワードでの機械的な比較セクション抽出に失敗する可能性がある。また比較対象地点数が過年度(40地点)と当年度(39地点)で異なる。'),
('r1-n4', 'kanagawa_river_monitoring_r1_sakawa_results', '[]', 'comparability', 'BOD、全窒素は平成21年度、平成26年度、今年度と段階的に低下していた。一方、SSは、平成21年度よりやや低く、平成26年度よりやや高かった。全燐は、平成21年度によりやや低く、平成26年度と同程度であった。', 7, 0, '3時点比較で指標ごとに増減方向が異なっており、『全体として改善傾向』と単純化して解釈しない方がよい。'),
('r1-n5', 'kanagawa_river_monitoring_r1_sakawa_results', '[]', 'comparability', '相模川では特に下流域の支川でDAIpoが大きく減少しており、酒匂川においては、本川も含めて全体的にDAIpoが下がる傾向にあった。付着藻類の出現に影響する水質や開空率の変化を整理したが、大きな変化はみられず、他の要因が影響していると考えられた。', 12, 1, '本書は酒匂川の報告書だが本文に『相模川では』という記述が混在しており（h26と全く同一の文言）、記述が酒匂川データに固有のものか使い回しかの判別ができない。DAIpo低下の要因も『他の要因』として特定されていない。'),
('r1-n6', 'kanagawa_river_monitoring_r1_sakawa_results', '[]', 'footnote', '平成31年度のSt.11は調査対象外。', 23, 1, '図-13（ナルコスゲの分布図）において、令和元年度（平成31年度）はSt.11が調査対象から除外されたことが明記されている。特定の年度・特定指標について地点が欠落しており、その地点を含む経年比較はできない。'),
('r1-n7', 'kanagawa_river_monitoring_r1_sakawa_results', '[]', 'footnote', '同一年度内で図-10・図-13は『平成31年度』、図-8・図-9・図-11・図-12・図-14は『令和元年度』とキャプション表記が混在（表-2の調査実施日表では『令和元年(平成31年)』と両方併記）。', 23, 1, '2019年度は元号が平成から令和に変わった年度であり、同一の調査年度が資料内で『平成31年度』『令和元年度』の両方の表記で登場する。年度文字列の完全一致に頼った時系列突合は失敗しうる。'),
(NULL, 'kasen_kokusei_sagami_fish', '[]', NULL, NULL, 1, 1, '調査対象は相模川流域全体ではなく京浜河川事務所の管理区域内に限定されており、区域の範囲が示されないため他年度・他区間との単純比較に注意が必要。'),
(NULL, 'kasen_kokusei_sagami_fish', '[]', NULL, NULL, 3, 1, '一部の重要種（絶滅危惧II類以上等）は保全上の理由で確認地点を非表示にしていると読み取れ（文末が切れており断定はできない）、地点別の比較可能性に影響する。'),
(NULL, 'kasen_kokusei_sagami_fish', '[]', NULL, NULL, 3, 1, '種数集計（合計種類数）から未同定個体を除外する運用ルールがあり、識別精度・努力量の違いにより年度間の種数が単純比較できない可能性がある。'),
(NULL, 'kasen_kokusei_sagami_fish', '[]', NULL, NULL, 3, 0, '重要種カテゴリーの定義注記であり、それ自体は時系列比較を直接妨げない。'),
(NULL, 'kasen_kokusei_sagami_fish', '[]', NULL, NULL, 3, 1, '参照マニュアルの版年度が文末切れで確認できず、本調査年度（平成19年度）との対応関係が不明瞭。マニュアル改定の有無が比較可能性に影響し得る。'),
(NULL, 'kasen_kokusei_sagami_benthos', '[]', NULL, NULL, 1, 1, '調査範囲は管理区域内に限定。範囲の明示がないため他調査との比較に注意。'),
(NULL, 'kasen_kokusei_sagami_benthos', '[]', NULL, NULL, 6, 1, '絶滅危惧II類以上の重要種は保全上の理由で確認地点情報が非公開になっている可能性が高く（文末切れ）、地点別比較ができない。'),
(NULL, 'kasen_kokusei_sagami_benthos', '[]', NULL, NULL, 6, 1, '未同定個体を種数集計から除外する運用があり、識別努力の違いで年度間の種数比較が影響を受ける可能性。'),
(NULL, 'kasen_kokusei_sagami_benthos', '[]', NULL, NULL, 6, 1, '参照するレッドリストが2006年版・2007年版の複数年にまたがっており、判定基準年が一意でないため重要種カテゴリーの経年比較に注意が必要。'),
(NULL, 'kasen_kokusei_sagami_benthos', '[]', NULL, NULL, 6, 1, '参照マニュアルが「平成18年度」版である旨が読み取れるが、本調査年度（平成20年度）との版の対応関係・改定履歴が本文からは確認できない。'),
(NULL, 'kasen_kokusei_sagami_birds', '[]', NULL, NULL, 1, 1, '調査は管理区域内に限定。区域の明示範囲がないため他調査との比較に注意。'),
(NULL, 'kasen_kokusei_sagami_birds', '[]', NULL, NULL, 3, 1, '絶滅危惧II類以上の種および猛禽類は保全上の理由で確認地点情報が伏せられており、地点別の比較ができない。'),
(NULL, 'kasen_kokusei_sagami_birds', '[]', NULL, NULL, 3, 0, '重要種カテゴリーの定義注記。'),
(NULL, 'kasen_kokusei_sagami_birds', '[]', NULL, NULL, 3, 0, '重要種カテゴリー（鳥類版レッドリスト2006年）の定義注記。'),
(NULL, 'kasen_kokusei_sagami_birds', '[]', NULL, NULL, 3, 1, '参照マニュアルが「平成18年度」版であるのに対し、本調査年度は平成21年度であり、マニュアル改定・版の対応関係が本文からは確認できない。'),
(NULL, 'kasen_kokusei_sagami_plants', '[]', NULL, NULL, 1, 1, '調査は管理区域内に限定。'),
(NULL, 'kasen_kokusei_sagami_plants', '[]', NULL, NULL, 13, 1, '環境省RL掲載種は表内で地点を「-」表記とし非公開にしており（例：コギシギシ、タコノアシ、ウスゲチョウジタデ、カワヂシャ、ミゾコウジュ）、地点別の比較ができない。'),
(NULL, 'kasen_kokusei_sagami_plants', '[]', NULL, NULL, 13, 1, '種数集計から未同定個体を除外する運用ルールが明記されており、識別精度・努力量の違いにより年度間の種数比較に影響しうる。'),
(NULL, 'kasen_kokusei_sagami_plants', '[]', NULL, NULL, 13, 1, '全国統一マニュアルに基づく旨は比較可能性にとって肯定的な記述だが、参照マニュアルの版年度（平成□年度、他文書では「平成18年度」の記載を確認）と本調査年度（平成17年度、マニュアルより前）との対応関係が不明瞭であり、マニュアル改定前後で集計基準が異なる可能性がある。'),
(NULL, 'kasen_kokusei_sagami_plants', '[]', NULL, NULL, 13, 0, '特定外来生物等カテゴリーの定義注記。'),
(NULL, 'kasen_kokusei_sagami_insects', '[]', NULL, NULL, 1, 1, '調査は管理区域内に限定。'),
(NULL, 'kasen_kokusei_sagami_insects', '[]', NULL, NULL, 22, 1, '環境省RL掲載種（例：キオビベッコウ、ヤマヒメメダカッコウムシ等の重要種欄に「希少」等の記載がある種）は地点情報が伏せられており、地点別の比較ができない。'),
(NULL, 'kasen_kokusei_sagami_insects', '[]', NULL, NULL, 22, 1, '同上（未同定個体の除外ルールが種数の年度間比較に影響しうる）。'),
(NULL, 'kasen_kokusei_sagami_insects', '[]', NULL, NULL, 22, 1, '参照マニュアルの版年度と本調査年度（平成18年度）との対応関係が不明瞭。'),
(NULL, 'kasen_kokusei_sagami_insects', '[]', NULL, NULL, 22, 0, '重要種カテゴリー（昆虫類版レッドリスト）の定義注記。'),
(NULL, 'kasen_kokusei_sagami_herptile_mammal', '[]', NULL, NULL, 1, 1, '調査は管理区域内に限定。'),
(NULL, 'kasen_kokusei_sagami_herptile_mammal', '[]', NULL, NULL, 1, 1, '同一の物理地点に2つの地点番号（②と④）が割り当てられており、他分類群調査の地点番号（例：魚類・底生動物の①〜③）や本文中の「調査地点の番号は、調査位置図の番号と対応しています」という説明と単純に対応付けられない。分類群間で地点番号の付番方式が異なる可能性を示唆する。'),
(NULL, 'kasen_kokusei_sagami_herptile_mammal', '[]', NULL, NULL, 2, 1, '絶滅危惧II類以上の重要種は保全上の理由で確認地点情報が伏せられている可能性が高く（文末切れ）、地点別比較ができない。'),
(NULL, 'kasen_kokusei_sagami_herptile_mammal', '[]', NULL, NULL, 2, 1, '未同定個体を種数集計から除外する運用があり、識別努力の違いにより年度間比較に影響しうる。'),
(NULL, 'kasen_kokusei_sagami_herptile_mammal', '[]', NULL, NULL, 2, 1, '調査年度自体は平成16年度（2004年度）であるのに、参照するレッドリストは2006年・2007年版であり、判定基準の年と調査実施年が一致しない（レッドリストが調査後に更新された基準を遡って適用している可能性）。'),
('suigen_hozen_final_eval_n001', 'suigen_hozen_final_eval', '[]', 'footnote', '家族経営体の林業所得は減少しており、森林所有者面積100～500haの家族経営体平均でも林業単体ではほとんど利益が出ない状況', 15, 0, '個別統計値の補足説明であり時系列比較への直接影響は小さい'),
('suigen_hozen_final_eval_n002', 'suigen_hozen_final_eval', '[]', 'survey_scope', '（一般財源事業約135億円/年、特別対策事業約40億円/年）※令和3年までの15年平均', 24, 1, '単年度値ではなく15年間の平均値であるため、単年度実績と単純比較できない'),
('suigen_hozen_final_eval_n003', 'suigen_hozen_final_eval', '[]', 'definition_change', '注1　「土壌保全対策の推進」について　平成19年度以降に新たに判明した課題に対応するため、新たに「土壌保全対策の推進」を特別対策事業へ位置付けました。', 25, 1, '第1期には存在しなかった事業区分が途中から新設されたため、期間をまたいだ事業別実績の単純比較ができない'),
('suigen_hozen_final_eval_n004', 'suigen_hozen_final_eval', '[]', 'definition_change', '注2　「渓畔林整備事業」について　第2期実行計画まで実施していた「渓畔林整備事業」は、モデル林を整備し効果を検証して整備手法を確立したことから、独立した事業とせずに、同事業で得られた手法を「水源の森林づくり事業」などにおいて展開することとしました。', 25, 1, '渓畔林整備事業という指標区分が第3期以降廃止され他事業に統合されたため、時系列の事業別実績を接続できない'),
('suigen_hozen_final_eval_n005', 'suigen_hozen_final_eval', '[]', 'definition_change', '注3　「生活排水処理施設の整備促進」について　水源環境の負荷軽減対策では、ダム集水域の公共下水道整備に時間を要している地域について、浄化槽による整備も含めた弾力的な対応を図ることが合理的であることから、「県内ダム集水域における公共下水道の整備促進」と「県内ダム集水域における合併処理浄化槽の整備促進」を統合し、新たに「生活排水処理施設の整備促進」としました。', 25, 1, '2つの事業区分が統合され新指標になったため、統合前後の実績を単純に接続・比較できない'),
('suigen_hozen_final_eval_n006', 'suigen_hozen_final_eval', '[]', 'footnote', '※21年度執行額には20年度からの明許繰越 3億2,708万円を含む。', 43, 1, '単年度執行額に前年度からの繰越額が含まれており、年度間の執行額の単純比較を歪める'),
('suigen_hozen_final_eval_n007', 'suigen_hozen_final_eval', '[]', 'footnote', '※　年度ごとに端数処理しているため、合計は一致しない。', 44, 0, '端数処理の注記であり数値の実質的な意味を変えないため時系列比較への影響は軽微'),
('suigen_hozen_final_eval_n008', 'suigen_hozen_final_eval', '[]', 'comparability', '※3時点のデータが揃うモニタリング地点 計28地点で集計（丹沢中低標高16、小仏4、箱根8）／※第3期データには、シカ定着により急激な植生劣化を示す地点も含まれる。／※3時点を通して低調な地点があり、一部のヒノキ林など。（ヒノキ林でも良好な地点あり。）', 59, 1, '集計対象地点が限定的（28地点）で構成に偏りや例外事例が含まれることを明示しており、期間比較時に事業効果と外的要因の混同に注意が必要'),
('suigen_hozen_final_eval_n009', 'suigen_hozen_final_eval', '[]', 'comparability', '※3時点のデータが揃うモニタリング地点、計72地点で集計（丹沢高標高38、丹沢中低標高28、箱根6）／※丹沢の第2期以降ではササ類の一斉開花・枯死、箱根の第3期ではシカ定着など、諸要因による急激な植生劣化を示す地点も含まれる。', 60, 1, '植生被覆率の変化には事業効果以外の外的要因（ササの一斉枯死、シカの新規定着）が混入しており、単純な時系列比較は事業効果を誤って解釈する恐れがある'),
('suigen_hozen_final_eval_n010', 'suigen_hozen_final_eval', '[]', 'comparability', '相模湖の水質については、全リンの濃度については下図のとおり減少傾向は確認されませんでした。…水源環境保全事業の負荷量削減のみでは水質改善効果が確認されなかったと考えられました。', 66, 1, 'リン濃度に減少傾向がみられない要因として富士山麓地下水由来の負荷など事業外の要因が指摘されており、事業効果と外的要因を区別せずに時系列比較すると誤解を招く'),
('suigen_hozen_final_eval_n011', 'suigen_hozen_final_eval', '[]', 'comparability', '本事業の相模川・酒匂川の水質調査結果から森林地域でも窒素酸化物の濃度が減少していることから、本事業の取組だけでなく広域的な発生源からの窒素負荷量の減少も影響している可能性が考えられました。', 68, 1, '観測された濃度変化が本事業単独の効果か、広域的な外的要因（大気由来窒素の減少等）によるものか切り分けられないと明記されており、事業効果としての時系列比較には注意が必要'),
('suigen_hozen_final_eval_n012', 'suigen_hozen_final_eval', '[]', 'survey_scope', '過去の測定結果から上流の測定値について、事業実施前後で同程度の値（BOD値:1.2〜3.2mg/Lの範囲）を示したデータを抽出し、上流側と下流側の測定値を比較した', 85, 1, '比較のため特定のBOD値範囲（1.2〜3.2mg/L）のデータのみを抽出しており、全期間の生データをそのまま用いた時系列比較とは異なる母集団を用いている'),
('suigen_hozen_final_eval_n013', 'suigen_hozen_final_eval', '[]', 'comparability', 'なお、河川・水路における自然浄化対策の推進事業を実施した42箇所の河川・水路について、工事開始前と工事後のBODを測定したところ、下図の通り、概ね改善の傾向が見て取れました。しかしながら、このモニタリングは、季節に伴う水量の変化などは考慮していないため、参考までに提示します。', 87, 1, '季節変動による水量差を統制していないと報告書自身が明記し、「参考まで」に留めるべきとしている'),
('suigen_hozen_final_eval_n014', 'suigen_hozen_final_eval', '[]', 'survey_scope', '県民参加型調査は5年に一度実施する河川での大規模な水質・生物調査を補完する目的で、毎年度実施している調査です。平成20年度から調査を開始し、新型コロナ感染症の影響で新規の調査員募集ができなかった令和2，3年度(赤で示した期間)を除くと参加人数は順調に増加しており', 79, 1, 'コロナ禍で令和2・3年度は新規調査員を募集できず調査実施体制が他年度と異なるため、その期間を含めた参加人数等の時系列比較は歪む可能性がある'),
('suigen_hozen_final_eval_n015', 'suigen_hozen_final_eval', '[]', 'definition_change', '今回結果（令和4年度）の「事業理解度の設問あり」（回収800票・有効回答437票・有効回答率54.6%・推定支払い意思額964円/月・世帯）と「事業理解度の設問なし」（回収800票・有効回答682票・有効回答率85.3%・推定支払い意思額913円/月・世帯）、前回結果（平成26年度、事業理解度の設問なし、回収800票・有効回答690票・有効回答率86.3%・推定支払い意思額887円/月・世帯）', 84, 1, '同一年度でも設問の有無によって有効回答率や推定支払意思額が異なり、前回調査（H26）は「事業理解度の設問なし」方式のみで実施されているため、設問設計の違いを無視した単純な数値比較はできない'),
('suigen_hozen_final_eval_n016', 'suigen_hozen_final_eval', '[]', 'definition_change', '前回、平成26(2014)年度に行ったCVMとは設問が異なっていたため、比較のため設問を揃えると、平成26(2014)年度は365億円/年であり、令和4(2022)年度は402億円/年となります。', 85, 1, '報告書自身が「前回とは設問が異なっていた」と明記し、設問を揃えて再計算した値（365億円/年・402億円/年）を用いるよう案内している。公表値（272億円/年）をそのまま前回結果と比較すると設問差を無視することになる'),
('suigen_hozen_final_eval_n017', 'suigen_hozen_final_eval', '[]', 'comparability', '費用として特別対策事業のみを計上することは実際の費用を過小にし、費用対効果を過大なものにすることになります。一方、一般財源等で実施している事業を全て含めた場合は…実際の費用を過大とし、費用対効果を過小なものとします。結果として実際の費用対効果は、1.6〜6.8の間にあると考えられます', 85, 0, '同一年度内での費用計上範囲（特別対策事業のみ／一般財源等含む全体）の選択により費用対効果指標（1.6〜6.8）が大きく振れることを説明したものであり、時系列比較というより算出方法の選択に関する留保'),
('suigen_hozen_final_eval_n018', 'suigen_hozen_final_eval', '[]', 'comparability', 'また、関東地方では、度々取水制限が行われています。利根川水系では平成19(2007)年以降、通算159日間の取水制限が行われていますが、神奈川県では同期間に取水制限は行っていません。', 86, 0, '他水系との比較であり、本報告書内の時系列データの比較可能性には直接影響しない参考情報'),
('suigen_hozen_final_eval_n019', 'suigen_hozen_final_eval', '[]', 'comparability', '本県とは事業内容が異なること（殆どの府県の事業内容は森林整備であり、生活排水対策などの水関係の事業を実施しているのは、本県と茨城県のみ）、本県の税収規模が突出して多いこと（令和4(2022)年度の税収規模では、本県42億円に対し、長野6.9億円、大分3.2億円、長崎3.9億円）から、相対的な比較とはなりません', 93, 0, '森林環境税等導入他府県との事業評価体制比較について、事業内容・税収規模が大きく異なるため「相対的な比較とはならない」と明記された都道府県間比較の限界説明（時系列比較ではない）'),
('suigen_hozen_final_eval_n020', 'suigen_hozen_final_eval', '[]', 'comparability', 'この評価手法については、世界的にも事例がまだまだ少ないことから相対的な評価を行うことが難しいこと、大綱策定より後に出来た基準のため、評価ができない項目もあるなど、試行的な評価ではありますが、本県の順応的管理について評価できるものと判断できます。', 90, 0, 'IUCN NbS世界標準を用いた自己評価について、他事例が少なく相対評価が困難であり、大綱策定後にできた基準のため評価不能項目がある試行的評価であると明記'),
('suigen_hozen_final_eval_n021', 'suigen_hozen_final_eval', '[]', 'comparability', '現在までの変化としては、横浜地方気象台の観測による年平均降水量には、長期的な変化傾向は見られません。一方で、全国的には、一時間降水量50mm以上の短時間強雨の発生回数は、長期的に有意な上昇傾向を示しています。', 100, 0, '局地（横浜地方気象台）の観測結果と全国的傾向を対比しており、指標の空間スケールの違いに注意を促す説明。時系列比較そのものを妨げるものではないが解釈時の混同に注意'),
('suigen_hozen_final_eval_n022', 'suigen_hozen_final_eval', '[]', 'footnote', '※シカの好まない植物種であっても地表が覆われれば土壌は保全されます。しかし、長期的にみると森の樹木の世代交代が妨げられるなどの問題があります。', 19, 0, '生態学的な留保説明であり数値の時系列比較には直接影響しない'),
('tanzawa_shika_r6_p4_note1', 'tanzawa_shika_r6', '["p4_t1"]', 'footnote', '注１）R6年度当初計画合計　4,743頭', 4, 0, '計画値の補足情報であり、実績値の時系列比較そのものを妨げる記述ではない。ただし表中のR6計画Bの内訳合計(5,108)とは一致しない当初計画値であることに注意。'),
('tanzawa_shika_r6_p4_note2', 'tanzawa_shika_r6', '["p4_t1"]', 'comparability', '注２）R5年度の県自然公園担当部局、国立公園管理者、国有林管理者の捕獲数は箱根町に含まれる', 4, 1, '表I-1-1のR5実績C列のうち、県自然公園担当部局・国立公園管理者・国有林管理者の各行は、R5年度データでは箱根町分がどこか別区分(おそらく市町村扱い)にまとめられており、R6年度の内訳との単純な行単位比較ができない。実際にこれらの行のR5実績Cはいずれも「－」表記になっている。'),
('tanzawa_shika_r6_p4_note3', 'tanzawa_shika_r6', '["p4_t1"]', 'definition_change', '※内訳ごとの捕獲数については、参考資料（P31）を参照', 4, 0, '参照先の指示であり、それ自体は比較可能性を妨げる記述ではない。'),
('tanzawa_shika_r4_p3_note1', 'tanzawa_shika_r4', '["p3_t1"]', 'comparability', '県実施合計 （a保護管理区域＋d定着防止区域）　（）内：民間事業者等委託', 3, 1, 'R4年度実績の概要表（表I-1-1）は、R6年度版の同名表と行構成が異なる。R4版には「県実施合計」「（）内：民間事業者等委託」という独自の集計行があり、また定着防止区域の内訳がd,e,fの3区分のみ（R6版はd,e,f,g,hの5区分で、県森林担当部局・県自然公園担当部局・国立公園管理者・国有林管理者を独立行として分離）。同じ『計(d)』であっても年度により内包する内訳範囲が異なる可能性があり、行単位での年度間比較は注意が必要。'),
('tanzawa_shika_r6_n001', 'tanzawa_shika_r6', '[]', 'comparability', '林業被害について：造林木の樹皮剥ぎや枝葉の採食は県内の各地で見られているが、被害時期の把握、被害額算定が難しい。そのため、令和6年度の被害額は0円となっている。', 33, 1, '被害額0円は実際の被害が消失したことを意味せず算定困難によるものであり、年度間の被害額を単純比較すると誤解を招く。'),
('tanzawa_shika_r6_n002', 'tanzawa_shika_r6', '[]', 'definition_change', '相模原市での保護管理区域は、津久井地区（青根、青野原、青山、太井、鳥屋、中野、長竹、根小屋、又野、三井、三ケ木）が該当する。', 33, 1, '「相模原市」の集計範囲が保護管理区域と定着防止区域とで異なる地区を指しており、単純な市町村名の一致だけで経年比較・区域比較を行うと誤る。'),
('tanzawa_shika_r6_n003', 'tanzawa_shika_r6', '[]', 'comparability', '狩猟免許の大量更新が3年ごとに訪れるので、その年は前年と比較し、狩猟免許所持者数が減少する傾向にある（上記表では平成6年度から3年ごと）。', 34, 1, '3年周期の制度的な減少パターンがあるため、前年比較のみで実態の増減トレンドを判断すると誤る。'),
('tanzawa_shika_r6_n004', 'tanzawa_shika_r6', '[]', 'comparability', '昭和53年（1978年）から3年ごとの有効期限制になったため大量更新年が発生。', 34, 1, '免許更新周期の制度的背景であり、n003と合わせて経年比較時に考慮が必要。'),
('tanzawa_shika_r6_n005', 'tanzawa_shika_r6', '[]', 'footnote', '1人で複数の免許を取得している場合もあるため、合計（人数）は、種別の合計と一致しない。', 34, 0, '合計値と内訳の非整合に関する説明であり、年度をまたいだ比較そのものを妨げるものではない。'),
('tanzawa_shika_r6_n006', 'tanzawa_shika_r6', '[]', 'definition_change', '第4次計画までのシカ植生定点調査、シカ森林一体的管理植生定点調査、水源林植生定点調査の調査地の重複や林相、柵の有無、継続の必要性などを考慮し、第5次計画からは、「シカ植生定点調査」（広葉樹林）は72地点、「水源林植生定点調査」（スギ、ヒノキ人工林主体）は23地点としてモニタリング地点の統合と整理を図り、他の地点では必要な際に調査することとした。', 30, 1, '第4次計画以前と第5次計画以降で調査地点数・調査体系そのものが変更されており、植生モニタリング指標の経年比較は単純にできない。'),
('tanzawa_shika_r6_n007', 'tanzawa_shika_r6', '[]', 'survey_scope', '各計画期間中の1〜3月捕獲、3歳以上メスについて平均値を算出。※第2次計画以降継続的に管理捕獲を実施している管理ユニットでの捕獲個体について集計（1次計画期間は2次計画以降継続実施管理ユニットの一部で捕獲実施）', 29, 1, '集計対象となる管理ユニットの範囲が計画期間ごとに異なるため、腎脂肪率・妊娠率の経年比較には注意が必要。'),
('tanzawa_shika_r6_n008', 'tanzawa_shika_r6', '[]', 'survey_scope', '令和元年度未実施メッシュ', 28, 1, '令和元年度は一部メッシュで糞塊密度調査が未実施であり、他年度との分布図・件数の単純比較はできない。'),
('tanzawa_shika_r6_n009', 'tanzawa_shika_r6', '[]', 'footnote', '()は計画変更', 4, 1, '括弧書きの数値は当初計画から変更された計画数であることを示す注記であり、これを区別せずに「計画」欄の数値を年度間で比較すると誤る。'),
('tanzawa_shika_r4_n001', 'tanzawa_shika_r4', '[]', 'survey_scope', '令和元年度の台風被害が一部の林道で残っていること、また、その後の豪雨により通行困難となった林道もあったことから、一部管理ユニットでの捕獲作業が制限された。', 3, 1, '台風・豪雨による林道の通行制限という外的要因で一部管理ユニットの捕獲作業が制限されており、当該年度の捕獲実績を他年度と単純比較すると過小評価につながる。'),
('tanzawa_shika_r4_n002', 'tanzawa_shika_r4', '[]', 'definition_change', '第3次計画までは、針葉樹人工林と広葉樹林の計50地点で林床植生のモニタリング調査を約5年おきに実施してきた。第4次計画からは、調査地点を整理し、林相が針葉樹人工林であり、かつ目標林型が針広混交林または巨木林の23地点を対象として、林床植生に加えて林分構造を調査することで、目標林型への誘導状況を把握することとした。', 29, 1, '調査地点数・対象林相が第3次計画までと第4次計画以降で変更されており、水源林の植生モニタリング結果の経年比較には調査体系の違いを考慮する必要がある。'),
('tanzawa_shika_r4_n003', 'tanzawa_shika_r4', '[]', 'definition_change', '第3次計画までのシカ植生定点調査、シカ森林一体的管理植生定点調査、水源林植生定点調査の調査地の重複や林相、柵の有無、継続の必要性などを考慮し、第4次計画からは、「シカ植生定点調査」（広葉樹林）は72地点、「水源林植生定点調査」（スギ、ヒノキ人工林主体）は23地点としてモニタリング地点の統合と整理を図り、他の地点では必要な際に調査することとした。', 29, 1, '第3次計画以前と第4次計画以降で調査体系そのものが変更されており、植生モニタリング指標の経年比較は単純にできない。'),
('tanzawa_shika_r4_n004', 'tanzawa_shika_r4', '[]', 'comparability', '林業被害について：造林木の樹皮剥ぎや枝葉の採食は県内の各地で見られているが、被害時期の把握、被害額算定が難しい。令和4年度の被害報告は1件あり、枯死にいたらない樹皮剥ぎであり、被害額は0円となっている。', 32, 1, '被害額0円は実態の被害消失を意味せず算定困難によるものであり、年度間の被害額を単純比較すると誤解を招く。'),
('tanzawa_shika_r4_n005', 'tanzawa_shika_r4', '[]', 'definition_change', '相模原市での保護管理区域は、津久井地区（青根、青野原、青山、太井、鳥屋、中野、長竹、根小屋、又野、三井、三ケ木）が該当する。', 32, 1, '「相模原市」の集計範囲が保護管理区域と定着防止区域とで異なる地区を指しており、単純な市町村名の一致だけで比較すると誤る。'),
('tanzawa_shika_r4_n006', 'tanzawa_shika_r4', '[]', 'comparability', '狩猟免許の大量更新が3年ごとに訪れるので、その年は前年と比較し、狩猟免許所持者数が減少する傾向にある（上記表では平成6年度から3年ごと）。', 33, 1, '3年周期の制度的な減少パターンがあるため、前年比較のみで実態の増減トレンドを判断すると誤る。'),
('tanzawa_shika_r4_n007', 'tanzawa_shika_r4', '[]', 'comparability', '昭和53年（1978年）から3年ごとの有効期限制になったため大量更新年が発生。', 33, 1, '免許更新周期の制度的背景であり、n006と合わせて経年比較時に考慮が必要。'),
('tanzawa_shika_r4_n008', 'tanzawa_shika_r4', '[]', 'footnote', '1人で複数の免許を取得している場合もあるため、合計（人数）は、種別の合計と一致しない。', 33, 0, '合計値と内訳の非整合に関する説明であり、年度をまたいだ比較そのものを妨げるものではない。'),
('tanzawa_shika_r4_n009', 'tanzawa_shika_r4', '[]', 'survey_scope', '令和元年度未実施メッシュ', 27, 1, '令和元年度は一部メッシュで糞塊密度調査が未実施であり、他年度との分布図・件数の単純比較はできない。'),
('tanzawa_shika_plan5_n001', 'tanzawa_shika_plan5', '[]', 'definition_change', '（※第3次計画中は「分布拡大防止区域」、第2次計画中は「監視区域」）', 2, 1, '現在の「定着防止区域」は計画次第で「分布拡大防止区域」「監視区域」と呼称が異なっていたため、計画期をまたいだ捕獲実績等の比較には名称の読み替えが必要。'),
('tanzawa_shika_plan5_n002', 'tanzawa_shika_plan5', '[]', 'comparability', '農業被害面積は、2000（平成12）年度以前は被害の見られた農地の全面積、2001（平成13）年度以降は実際に被害にあった部分の面積の集計値（2001（平成13）年度に調査方法改正）', 43, 1, '2001年度に被害面積の集計対象の定義そのものが変更されており、それ以前と以降の被害面積を単純比較できない。'),
('tanzawa_shika_plan5_n003', 'tanzawa_shika_plan5', '[]', 'definition_change', '農業被害の数値は、2011（平成23）年度以前は保護管理区域の集計値', 43, 1, '2011年度以前は集計範囲が保護管理区域のみであり、それ以降の全区域集計値とは対象範囲が異なるため単純比較できない。'),
('tanzawa_shika_plan5_n004', 'tanzawa_shika_plan5', '[]', 'definition_change', '区分の「定着防止区域」の2012（平成24）〜2016（平成28）年度における名称は「分布拡大防止区域」。', 43, 1, '同一区分でも年度により名称が異なっており、n001と合わせて表記の読み替えが必要。'),
('tanzawa_shika_plan5_n005', 'tanzawa_shika_plan5', '[]', 'definition_change', '2007（平成19）年度に鳥獣保護法が改正され、網・わな猟免許が網猟免許、わな猟免許に区分され、2009（平成21）年度に移行が完了した。', 44, 1, '免許区分（網・わな猟が単一区分から2区分へ分離）が制度改正により変わっており、2009年度前後の免許者数を区分ごとに単純比較できない。'),
('tanzawa_shika_plan5_n006', 'tanzawa_shika_plan5', '[]', 'footnote', '実人数とは1人で複数の免許を所持している者を1名として集計したもの', 44, 0, '集計方法自体は全期間共通のルールであり、経年比較を直接妨げるものではない。'),
('tanzawa_shika_plan5_n007', 'tanzawa_shika_plan5', '[]', 'survey_scope', '（注）2023(R5).1現在；広域の被害防止計画として、足柄上地域鳥獣被害防止計画（2015(H27)〜2017(H29)）がある。【南足柄市、中井町、大井町、松田町、山北町、開成町が策定】', 45, 1, '個別市町の計画とは別に広域計画が存在した期間があり、市町別の策定状況集計だけでは実態把握が不十分になりうる。'),
('tanzawa_shika_plan5_n008', 'tanzawa_shika_plan5', '[]', 'survey_scope', '4次計画中のデータは2022（令和4）年度分は含まれていない。', 42, 1, '「4次」区分の実績値に令和4年度分が含まれておらず、他の区分（1次〜3次）と単純に並べて比較すると集計期間が不揃いになる。'),
('tanzawa_shika_plan5_n009', 'tanzawa_shika_plan5', '[]', 'survey_scope', '中川川上流A・B・C、丹沢湖B、丹沢中央A・B・D、丹沢南麓B・C・D、中津川B・Cで1月〜3月に捕獲された3歳以上のメス', 42, 1, '腎脂肪率・妊娠率の集計対象が特定の管理ユニット・月・性別・年齢に限定されており、区域全体の代表値として単純比較するには注意が必要。'),
('n_rdb2006_animals_001', 'kanagawa_rdb2006_animals', '["animals2006_鳥類"]', 'definition_change', '＊鳥類では、繁殖期と非繁殖期で異なるカテゴリーに属する種があるが、その場合ここではより厳しいカテゴリーで集計してある。', 1, 1, '鳥類の一部の種は(繁)と(非)で異なるカテゴリーを持つ複合評価であり、本CSVのcategory_jaはPDF記載の(繁)/(非)表記をそのまま両方残しているため、単純に「1種1カテゴリー」として集計・比較すると県の公式集計(より厳しい方で1本化)と数え方が変わる。時系列比較や単純集計の際は要注意。'),
('n_rdb2006_animals_002', 'kanagawa_rdb2006_animals', '["animals2006_哺乳類", "animals2006_鳥類", "animals2006_爬虫類", "animals2006_両生類", "animals2006_汽水・淡水魚類"]', 'comparability', '本PDF(神奈川県レッドリスト集計結果・一覧, 2006年版)のカテゴリー体系(絶滅/野生絶滅/絶滅危惧Ⅰ類・ⅠA類・ⅠB類/絶滅危惧Ⅱ類/準絶滅危惧/減少種/希少種/要注意種/注目種/情報不足/不明種/絶滅のおそれのある地域個体群)は、現行(2020年版植物編等)の英字コード付きカテゴリー(EX/EW/CR/EN/VU/NT/DD/LP等)とは体系が異なり、本PDF中に英字コードの記載は一切ない。さらに『旧判定』列には絶滅種A/B, 希少種Ⅰ, 減少種G/H, 健在種Ⅰ/J, 絶滅危惧種D/E/F/L, 評価検討種 という第三の(1995年前後と推測される、本PDF内に年次の明記なし)分類体系が併記されている。', NULL, 1, '2006年版・(旧判定列が示す)より古い版・2020年版以降版の3つの体系はカテゴリー名も区分数も異なり、対応関係を示す公式な変換表が本PDF中に見当たらないため、機械的な読み替え・突合はできない。カテゴリー記号の意味を推測しないという方針上、本CSVでは原文のカテゴリー名をそのまま残し、category_code(英字コード)は全件空欄にしてある。'),
('n_rdb2006_animals_003', 'kanagawa_rdb2006_animals', '[]', 'survey_scope', '評価結果一覧（分類群ごと、カテゴリー順で掲載）', 1, 0, '本PDF(RedData2006_shukeikekka_ichiran.pdf, 全29ページ)は、神奈川県立生命の星・地球博物館サイトのリンク文言にある「634ページ」の本冊そのものではなく、本冊の中の『評価結果一覧』章だけを抜き出したPDFである(掲載元のリンクテキストが指す634ページは本冊の総ページ数であり、本PDFファイル自体は29ページ)。各行の「ページ」列は本冊(634頁)側のページ番号を指しており、本PDF内のページ番号(1〜29)とは別物のため、note_ja に「原典...掲載ページ」として本冊側のページ番号をそのまま引用してある。');
INSERT INTO "notes" ("note_id", "doc_id", "table_ids", "kind", "text", "page", "blocks_timeseries", "reason") VALUES
('n_rdb2006_animals_004', 'kanagawa_rdb2006_animals', '[]', 'survey_scope', '(全29ページ中に「貝類」「甲殻類」「無脊椎」等のキーワードは一度も出現しない)', NULL, 0, '2006年版の本評価結果一覧には、哺乳類・鳥類・爬虫類・両生類・汽水淡水魚類・昆虫類・クモ類の7分類群のみが掲載されており、『その他無脊椎動物』(貝類・甲殻類等)に相当する区分は存在しない。ユーザー依頼にあった『その他無脊椎動物』のデータは、本PDFには含まれていない(取得漏れではなく原資料に該当区分自体が無い)。'),
('n_rdb2006_animals_005', 'kanagawa_rdb2006_animals', '[]', 'footnote', '＊菌類では「／情報不足」と付記されたカテゴリーに属する種があるが、ここではそれを付記してないものとみなして集計してある。', 1, 0, '菌類に関する注記であり、本タスクの対象(動物編)には直接関係しないが原文のまま記録する。'),
('n_rdb2006_animals_006', 'kanagawa_rdb2006_animals', '[]', 'definition_change', '本PDF中に学名(ラテン語二名法)の記載は一切なく、和名と科名(和名表記)のみが記載されている。', NULL, 0, '和名から学名を推測して補完することは禁止されているため、kanagawa_redlist_animals_2006.csv の scientific_name は全件空欄。taxa テーブルへの投入も taxon_id=''wamei:<和名>'' 方式(学名なし)で行っている。GBIF学名照合(FR未達)は学名が無いため原理的に実施不可能。'),
('n_rdb2022_plants_001', 'kanagawa_rdb2022_plants_outline', '[]', 'comparability', '選定種一覧（神奈川県レッドリスト）※分類群ごとにカテゴリー順に掲載', 10, 1, '本表は種ごとに「県RDB2006」(2006年版カテゴリー)と「環境省RL2020」(国カテゴリー)を併記しており、新旧対照表としての価値は高い。ただし維管束植物809種は既存のkanagawa_redlist(2020年版CSV, 807種)と種数が一致せず、カテゴリー体系(2022年版はIA類/IB類の分割がありCR/EN別コード、2020年版CSVはCR+ENを1区分として扱う行がある等)も完全には一致しない。どちらが最新かは2022年版の方が新しいが、既存のtaxaテーブルは2020年版CSVで構築済みのため、本タスクでは無条件の上書き・統合はせず、kanagawa_redlist_plants_2022.csv として別ファイルで提供するに留めた(taxaへの統合は人手判断が必要)。'),
('n_rdb2022_plants_002', 'kanagawa_rdb2022_plants_outline', '[]', 'definition_change', '本一覧表(p10-39)には学名(ラテン語二名法)の記載が無く、和名と科名等のみが記載されている。', NULL, 0, '和名から学名を推測して補完することは禁止されているため、kanagawa_redlist_plants_2022.csv の scientific_name は全件空欄。'),
('n_rdb2022_plants_003', 'kanagawa_rdb2022_plants_outline', '[]', 'footnote', '藻類(p35)のみ、表のレイアウトが他の3分類群(維管束植物・コケ植物・菌類)と異なる(6列構成の小表が複数個、縦書きカテゴリーセルの分割方法も異なる)。', 35, 0, '汎用の列マッピングでは正しく抽出できないため、pdfplumberのgrid抽出結果を直接目視確認し個別に転記した(18種、本文中の◆定義の合計と完全一致で検証済み)。'),
('biodic_6th_kanagawa_h16_n011', 'biodic_6th_kanagawa_h16', '[]', 'survey_scope', '平成16年度の調査実施個所は29か所であった。平成15年度もそのうちの10か所で調査を行っており、平成15年度、16年度どちらかの調査で目撃のあった調査区は12か所であった。生息密度は最大で1.4頭／㎞２（玄倉北東調査区）と、きわめて低密度であった（表３）。', 62, 1, '表３(カモシカの生息密度分布)は平成15年度と16年度で異なる調査区セット(29か所 vs 10か所、重複12か所)を1つの図表に混在させており、単一年度の面的な生息密度分布として単純比較できない。本報告書全体は平成16(2004)年度実施と明記されるが(p.2,p.5)、個別の分類群・指標では複数年度のデータが1指標に累積・混在するケースがある(本注記および既存n008参照)ため、分類群・指標ごとに集計対象年度が同一かどうかを個別に確認する必要がある。');
